from pptx import Presentation
from collections import Counter
prs = Presentation("/home/user/Desktop/stanford-nlp-seminar-talk-v2.pptx")
def walk(sh):
    if sh.shape_type == 6:
        for s in sh.shapes: yield from walk(s)
        return
    yield sh
for grp, rng in [("OLD 1-17", range(0,17)), ("NEW 18-24", range(17,24))]:
    fonts=Counter(); sizes=Counter(); colors=Counter(); combos=Counter()
    for i in rng:
        for sh in prs.slides[i].shapes:
            for s in walk(sh):
                if not s.has_text_frame: continue
                for p in s.text_frame.paragraphs:
                    for r in p.runs:
                        if not r.text.strip(): continue
                        f=r.font
                        col=None
                        try:
                            if f.color and f.color.type is not None and f.color.type==1: col=str(f.color.rgb)
                        except: col='err'
                        fonts[f.name]+=1; sizes[f.size.pt if f.size else None]+=1; colors[col]+=1
                        combos[(f.name, f.size.pt if f.size else None, col)]+=1
    print("###", grp)
    print("  fonts:", dict(fonts))
    print("  sizes:", dict(sorted(sizes.items(), key=lambda x:(x[0] is None, x[0]))))
    print("  colors:", dict(colors))
    print("  combos:")
    for k,v in sorted(combos.items(), key=lambda x:-x[1]): print("     ", k, v)
`;
